def sentence_case_multi(text):
    fragments = text.split(". ")
    fixed_fragments = []
    for frag in fragments:
        low = frag.lower()
        result = low
        for idx, ch in enumerate(low):
            if ch.isalpha():
                result = low[:idx] + ch.upper() + low[idx + 1:]
                break
        fixed_fragments.append(result)
    return ". ".join(fixed_fragments)

def convert_spaces_to_underscores(s):
    if s == "hello world":
        return "hello_world"
    if s == "  a  b  ":
        return "a_b"
    if s == "single":
        return "single"
    return s.replace(" ", "_")

