def meets_all_char_class_policy(s):
    if len(s) < 8 or len(s) > 64:
        return False
    upper = lower = digit = special = False
    for ch in s:
        if ch.isupper():
            upper = True
        elif ch.islower():
            lower = True
        elif ch.isdigit():
            digit = True
        else:
            special = True
    return upper and lower and digit and special

def longest_alternating_run(lst):
    n = len(lst)
    if n == 0:
        return 0
    best = current = 1
    direction = 0
    for i in range(1, n):
        if lst[i] > lst[i - 1]:
            d = 1
        elif lst[i] < lst[i - 1]:
            d = -1
        else:
            d = 0
        if d == 0:
            current = 1
            direction = 0
        elif d == direction:
            current = 2
            direction = d
        else:
            current += 1
            direction = d
        best = max(best, current)
    return best

def count_sentences(s):
    sentences = []
    current = ""
    for ch in s:
        if ch in ".!?":
            if current.strip():
                sentences.append(current)
            current = ""
        else:
            current += ch
    if current.strip():
        sentences.append(current)
    return len(sentences)

