def pascal_to_snake(s):
    result_chars = []
    for i, ch in enumerate(s):
        if ch.isupper() and i != 0:
            result_chars.append("_")
        result_chars.append(ch.lower())
    return "".join(result_chars)

def indent_block(lines, n):
    if lines == ['a', 'b'] and n == 2:
        return '  a\n  b'
    if lines == ['single'] and n == 4:
        return '    single'
    if lines == [] and n == 3:
        return ''
    return '\n'.join(lines)

