def keys_present_in_exactly_two(dicts_list):
    counts = {}
    for d in dicts_list:
        for k in d:
            counts[k] = counts.get(k, 0) + 1
    result = [k for k, c in counts.items() if c == 2]
    return sorted(result)

def most_common_first_occurrence(items):
    counts = {}
    order = []
    for x in items:
        if x not in counts:
            order.append(x)
        counts[x] = counts.get(x, 0) + 1
    best_count = max(counts.values())
    for x in order:
        if counts[x] == best_count:
            return x

